from .db import connect


def changed_since(watermark):
    """Customers changed after the last export's watermark (incremental export)."""
    with connect() as conn:
        return conn.execute(
            "SELECT id, name, email, tier, updated_at FROM customers "
            "WHERE updated_at > %(w)s ORDER BY updated_at, id",
            {"w": watermark},
        ).fetchall()
